WITH valores AS (SELECT 0 AS orden, N'__TODOS__' AS valor, N'Todos los estados' AS etiqueta UNION ALL SELECT 1, N'__DESCONOCIDO__', N'Desconocido / NULL' UNION ALL SELECT 2, p.order_status, p.order_status FROM dw.FactPedidos AS p WHERE p.order_status IS NOT NULL AND p.order_status NOT IN (N'__TODOS__', N'__DESCONOCIDO__') GROUP BY p.order_status) SELECT valor, etiqueta FROM valores ORDER BY orden, etiqueta;
